def offline_answer(intent: str, language: str, fallback: str) -> str:
    return OFFLINE_ANSWERS.get(intent, {}).get(language, fallback)

def generic(kind: str, language: str) -> str:
    return GENERIC[kind].get(language, GENERIC[kind]["en"])
